        });
        break;
      case is.blacklist:
        cht.delete();
        break;
      case is.antidelete:
        let deleted = await store.loadMessage(cht.id, cht[cht.type].key.id);
        await Data.utils({ cht: deleted, Exp, is: {}, store });
        let bodyText = Data.infos.interactive.antiDelete(cht, func, deleted);
        let contextInfo = {
          stanzaId: deleted.key.id,
