      if (!action) {
        return cht.reply(
          '❌ Gunakan perintah berikut:\n' +
            '• `.chess create <room>` - Buat game baru\n' +
            '• `.chess join <room>` - Gabung game\n' +
            '• `.chess start <room>` - Mulai game\n' +
